                    "sql": "drop table if exists public.r_for_rabbit_unicommerce_fact_items; create table public.r_for_rabbit_unicommerce_fact_items as select * from ( select \"shipping address pincode\" AS shipping_pincode, \"billing address pincode\" AS billing_pincode, \"channel name\" AS marketplace, \"channel name\" AS source, \"display order code\" AS order_id, \"display order code\" AS reference_code, \"shipping address phone\" AS phone, \"billing address name\" AS name, \"notification email\" AS email, upper(category) category, TO_CHAR(TO_TIMESTAMP(NULLIF(updated, \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS SHIPPING_LAST_UPDATE_DATE, \"item sku code\" AS sku, \"seller sku code\" AS Marketplace_sku, \"channel product id\" AS product_id, coalesce(\"item type name\",\"sku name\") AS product_name, currency, coalesce(\"shipping address city\", \"billing address city\") city, coalesce(\"shipping address state\", \"billing address state\") state, case when not(\"sale order status\" in (\'COMPLETE\',\'CANCELLED\')) and \"shipping package status code\" is null then \'UNFULFILLABLE\' else \"sale order status\" end AS order_status, \"invoice code\" as invoice_code, TO_CHAR(TO_TIMESTAMP(NULLIF(\"invoice created\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS invoice_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"order date as dd/mm/yyyy hh:mm:ss\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS order_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"shipping package creation date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS shipping_package_creation_date, cast(\"shipping charges\" AS double precision) AS shipping_price, 1 AS suborder_quantity, CAST(discount AS double precision) AS discount, CAST(\"tax value\" AS double precision) AS tax, CAST(\"selling price\" AS double precision) AS selling_price, \"shipping package code\" AS shippingPackageCode, \"shipping package status code\" AS shippingPackageStatus, \"sale order item code\" AS SaleOrderItemCode, \"sale order item code\" AS Sales_Order_Item_ID, \"tracking number\" AS AWB, facility AS Warehouse_Name, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Mode, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Method, \"shipping courier\" AS Courier, \"shipping courier status\" AS shipping_status, \"shipping tracking status\" as shipping_tracking_status, 1 AS shippedQuantity, null AS packing_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"dispatch date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS dispatch_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"ewaybill date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS ewaybill_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"delivery time\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS delivery_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"return date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS return_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"reverse pickup created date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS reverse_pickup_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"fulfillment tat\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS fulfillment_tat, \"reverse pickup code\" as reverse_pickup_code, \"return remarks\" as return_remarks, \"reverse pickup reason\" as reverse_pickup_reason, CASE WHEN \"return date\" IS NOT NULL AND TRIM(CAST(\"return date\" AS varchar)) <> \'\' AND LOWER(TRIM(CAST(\"return date\" AS varchar))) <> \'null\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN \"return date\" IS NOT NULL AND TRIM(CAST(\"return date\" AS varchar)) <> \'\' AND LOWER(TRIM(CAST(\"return date\" AS varchar))) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN \"return date\" IS NOT NULL AND TRIM(CAST(\"return date\" AS varchar)) <> \'\' AND LOWER(TRIM(CAST(\"return date\" AS varchar))) <> \'null\' THEN CAST(\"selling price\" AS double precision) ELSE 0 END AS return_sales, CASE WHEN lower(\"sale order status\") LIKE \'%cancel%\' OR lower(\"shipping courier status\") LIKE \'%cancel%\' THEN 1 ELSE 0 END AS cancelled_quantity, row_number() over (partition by \"display order code\",\"sale order item code\" order by TO_CHAR(TO_TIMESTAMP(NULLIF(updated, \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') desc) as rw from public.unicommerce_rabbit_db_get_sale_orders fi ) where rw = 1 ; drop table if exists public.r_for_rabbit_unicommerce_b2b_sales_report_fact_items; CREATE TABLE public.r_for_rabbit_unicommerce_b2b_sales_report_fact_items AS WITH ranked_data AS ( SELECT null AS customer_id, \"shipping address pincode\" AS pincode, \"channel name\" AS marketplace, \"channel name\" AS source, replace(\"display order code\",\'`\',\'\') AS order_id, replace(\"display order code\",\'`\',\'\') AS reference_code, \"shipping address name\" AS name, cast(null AS varchar) AS email, \"item sku code\" AS sku, \"item type name\" AS product_name, currency, coalesce(\"shipping address city\", \"billing address city\") city, coalesce(\"shipping address city\", \"billing address state\") state, \"sale order status\" AS order_status, CAST(NULLIF(\"order date as dd/mm/yyyy hh:mm:ss\", \'\') AS TIMESTAMP) AS Order_Date, CAST(NULLIF(TRIM(CAST(\"shipping charges\" AS VARCHAR)), \'\') AS FLOAT8) AS shipping_price, cast(\"total quantity\" as float8) AS suborder_quantity, CAST(NULLIF(TRIM(CAST(discount AS VARCHAR)), \'\') AS FLOAT8) AS discount, CAST(NULLIF(TRIM(CAST(\"tax value\" AS VARCHAR)), \'\') AS FLOAT8) AS tax, case when \"customer gstin\" <> \'\' then CAST(NULLIF(TRIM(CAST(\"selling price\" AS VARCHAR)), \'\') AS FLOAT8) else CAST(NULLIF(TRIM(CAST(\"selling price\" AS VARCHAR)), \'\') AS FLOAT8) end AS selling_price, \"sale order item code\" AS SaleOrderItemCode, \"sale order item code\" AS Sales_Order_Item_ID, Facility AS Warehouse_Name, \"payment type\" AS Payment_Mode, upper(\"payment type\") AS Payment_Method, 1 AS shippedQuantity, CAST(NULLIF(\"return date\", \'\') AS TIMESTAMP) AS return_date, CASE WHEN \"return date\" IS NOT NULL AND TRIM(CAST(\"return date\" AS VARCHAR)) <> \'\' AND LOWER(TRIM(CAST(\"return date\" AS VARCHAR))) <> \'null\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN \"return date\" IS NOT NULL AND TRIM(CAST(\"return date\" AS VARCHAR)) <> \'\' AND LOWER(TRIM(CAST(\"return date\" AS VARCHAR))) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN \"return date\" IS NOT NULL AND TRIM(CAST(\"return date\" AS VARCHAR)) <> \'\' AND LOWER(TRIM(CAST(\"return date\" AS VARCHAR))) <> \'null\' THEN CAST(NULLIF(TRIM(CAST(\"selling price\" AS VARCHAR)), \'\') AS FLOAT8) ELSE 0 END AS return_sales, \"cancelled quantity\" as cancelled_quantity, cast(null AS varchar) AS new_customer_flag, cast(null AS varchar) AS acquisition_product, null AS days_in_shipment, null AS acquisition_date, \"item sku code\" AS SKU_CODE, \"customer gstin\" as customer_gstin, \'UNICOMMERCE R FOR RABBIT B2B\' as data_source, ROW_NUMBER() OVER ( PARTITION BY \"display order code\", \"sale order item code\" ORDER BY CAST(NULLIF(\"order date as dd/mm/yyyy hh:mm:ss\", \'\') AS TIMESTAMP) DESC ) AS rn FROM public.unicommerce_rabbit_db_get_b2b_sale_orders ) SELECT customer_id, pincode, marketplace, source, order_id, reference_code, name, email, sku, product_name, currency, city, state, order_status, Order_Date, shipping_price, suborder_quantity, discount, tax, selling_price, SaleOrderItemCode, Sales_Order_Item_ID, Warehouse_Name, Payment_Mode, Payment_Method, shippedQuantity, return_date, return_flag, return_quantity, return_sales, cancelled_quantity, new_customer_flag, acquisition_product, days_in_shipment, acquisition_date, SKU_CODE, customer_gstin, data_source FROM ranked_data WHERE rn = 1;",
